parameters.jsCode:
const stats = $('Fetch All Stats').first().json;
const aiSummary = $input.first().json?.response || 'Résumé IA non disponible';
const report = {
  date: new Date().toISOString().split('T')[0],
  stats,
  ai_summary: aiSummary.substring(0, 1000),
  generated_at: new Date().toISOString()
};
return [{ json: report }];
